package com.tapeverify.copilot.util;
import com.tapeverify.copilot.entity.Loan; import java.math.*; import java.nio.charset.StandardCharsets; import java.security.*; import java.util.*;
public final class HashUtil { private HashUtil(){} public static String hash(Loan l){String input=String.join("|",s(l.getBatchId()),s(l.getSourceFileId()),s(l.getSourceLoanId()),s(l.getBorrowerId()),s(l.getBorrowerName()),d(l.getPrincipalAmount()),d(l.getCurrentBalance()),d(l.getInterestRate()),s(l.getPaymentStatus()),v(l.getDaysPastDue()),s(l.getBorrowerState()),s(l.getDocumentStatus()),v(l.getLastUpdatedAt()),s(l.getSourceSystem()),s(l.getLoanType()),v(l.getTermMonths()),s(l.getLoanPurpose()),s(l.getCreditGrade()),s(l.getEmploymentLength()),s(l.getIncomeBand()),v(l.getLastPaymentDate()),v(l.getOriginationDate()),v(l.getMaturityDate()),v(l.getStatus()));try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(input.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}} public static String hashBytes(byte[] bytes){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}} private static String s(String x){return x==null?"<null>":x.trim().replaceAll("\\s+"," ");}private static String d(BigDecimal x){return x==null?"<null>":x.setScale(2,RoundingMode.HALF_UP).toPlainString();}private static String v(Object x){return x==null?"<null>":x.toString();}}
